// lamina's docs site (todo B7a): Starlight, with the @lamina/pdf API reference generated by
// TypeDoc at build time and every internal link checked (starlight-links-validator fails the
// build on a broken one). Code on the pages is read from the tested example files
// (src/components/Snippet.astro), and the error table from fixtures/codes.json.
import { createHash } from "node:crypto";
import { copyFile, mkdir, readdir, readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import starlight from "@astrojs/starlight";
import { defineConfig } from "astro/config";
import starlightLinksValidator from "starlight-links-validator";
import starlightTypeDoc, { typeDocSidebarGroup } from "starlight-typedoc";

const ROOT = new URL("../../", import.meta.url);
const GOLDENS = new URL("fixtures/golden/examples/", ROOT);

/** Copies the examples' golden PDFs into the site at /examples/pdf/ (the gallery links them). */
const examplePdfs = {
  name: "lamina-example-pdfs",
  hooks: {
    "astro:build:done": async ({ dir }) => {
      const out = new URL("examples/pdf/", dir);
      await mkdir(out, { recursive: true });
      const copied = new Set();
      for (const name of await readdir(GOLDENS)) {
        if (!name.endsWith(".pdf")) continue;
        await copyFile(new URL(name, GOLDENS), new URL(name, out));
        copied.add(name);
      }
      // The links validator only knows pages, so check the gallery's PDF links here.
      const gallery = await readFile(new URL("examples/index.html", dir), "utf8");
      const missing = [...gallery.matchAll(/href="\/examples\/pdf\/([^"]+)"/g)]
        .map((m) => m[1])
        .filter((name) => !copied.has(name));
      if (missing.length > 0) throw new Error(`the gallery links PDFs that aren't goldens: ${missing.join(", ")}`);
    },
  },
};

/** The token in public/_headers that {@link inlineScriptHashes} replaces. */
const HASHES = "'inline-script-hashes'";

/** Every HTML file under `dir` (a file: URL), recursively. */
async function htmlFiles(dir) {
  const entries = await readdir(dir, { recursive: true });
  return entries.filter((name) => name.endsWith(".html")).map((name) => new URL(name, dir));
}

/**
 * Puts the SHA-256 of every inline script the build wrote (Starlight's theme and tabs, Expressive
 * Code's copy button) into the CSP of dist/_headers, so `script-src` allows exactly those and
 * the site's own files: no 'unsafe-inline' (ADR 0011 §4). A script added or changed by an
 * upgrade gets its hash on the next build.
 */
const inlineScriptHashes = {
  name: "lamina-csp-script-hashes",
  hooks: {
    "astro:build:done": async ({ dir }) => {
      const hashes = new Set();
      for (const file of await htmlFiles(dir)) {
        const html = await readFile(file, "utf8");
        for (const [, attributes, body] of html.matchAll(/<script(\s[^>]*)?>([\s\S]*?)<\/script>/g)) {
          if (/\ssrc=/.test(attributes ?? "") || body.length === 0) continue;
          hashes.add(`'sha256-${createHash("sha256").update(body, "utf8").digest("base64")}'`);
        }
      }
      const headersFile = new URL("_headers", dir);
      const headers = await readFile(headersFile, "utf8");
      if (!headers.includes(HASHES)) throw new Error(`public/_headers has no ${HASHES} to replace`);
      await writeFile(headersFile, headers.replace(HASHES, [...hashes].sort().join(" ")));
    },
  },
};

// A default export because that is how Astro reads its configuration.
export default defineConfig({
  // Telemetry is off in the package scripts (ASTRO_TELEMETRY_DISABLED).
  devToolbar: { enabled: false },
  integrations: [
    starlight({
      title: "lamina",
      description:
        "Create, read, edit and save PDFs from Rust and TypeScript: one Rust core, as WebAssembly in browsers, Node, Deno, Bun and Cloudflare Workers.",
      social: [{ icon: "github", label: "GitHub", href: "https://github.com/laudebugs/lamina" }],
      editLink: { baseUrl: "https://github.com/laudebugs/lamina/edit/main/apps/docs/" },
      lastUpdated: false,
      plugins: [
        starlightLinksValidator({
          errorOnLocalLinks: true,
          // The example PDFs aren't pages; the lamina-example-pdfs integration checks them.
          exclude: ["/examples/pdf/*"],
        }),
        starlightTypeDoc({
          entryPoints: [fileURLToPath(new URL("packages/pdf/src/index.ts", ROOT))],
          tsconfig: fileURLToPath(new URL("packages/pdf/tsconfig.build.json", ROOT)),
          output: "reference/pdf",
          sidebar: { label: "@lamina/pdf (TypeDoc)", collapsed: true },
          typeDoc: {
            // The wasm-bindgen types come from @lamina/wasm's dist/, which only `cargo xtask wasm`
            // builds: without it the records are named but not expanded, and the build goes on.
            skipErrorChecking: true,
            excludeInternal: true,
            excludePrivate: true,
            gitRevision: "main",
            sourceLinkTemplate: "https://github.com/laudebugs/lamina/blob/main/{path}#L{line}",
          },
        }),
      ],
      sidebar: [
        {
          label: "Start here",
          items: [
            { label: "Overview", link: "/" },
            { label: "Install", slug: "install" },
          ],
        },
        { label: "Quick start", items: [{ autogenerate: { directory: "quick-start" } }] },
        { label: "Guides", items: [{ autogenerate: { directory: "guides" } }] },
        { label: "Examples", link: "/examples/" },
        {
          label: "Reference",
          items: [
            { label: "Rust API (rustdoc)", slug: "reference/rust" },
            { label: "Error and warning codes", slug: "reference/codes" },
            typeDocSidebarGroup,
          ],
        },
      ],
    }),
    examplePdfs,
    inlineScriptHashes,
  ],
});
